// Cache-breakpoint placement in an agent-loop call.
import Anthropic from '@anthropic-ai/sdk';

const client = new Anthropic();

export async function cachedAgentTurn(
  systemPrompt: string,
  toolDefs: Anthropic.Tool[],
  priorMessages: Anthropic.MessageParam[],
  newUserContent: Anthropic.MessageParam,
) {
  return client.messages.create({
    model: 'claude-sonnet-4-5',
    max_tokens: 2048,
    // (1) System with cache marker — entire system prompt is cached up to here.
    system: [
      {
        type: 'text',
        text: systemPrompt,
        cache_control: { type: 'ephemeral' },
      },
    ],
    // (2) Tool defs — Anthropic caches them implicitly along with the system
    // when cache_control sits on the system block. For explicit control, mark
    // the last tool's input_schema with cache_control as well.
    tools: toolDefs,
    // (3) Prior conversation: mark the LAST message of the prior list with
    // cache_control. Each subsequent call extends the cache to one more turn.
    messages: [
      ...priorMessages.map((m, i) =>
        i === priorMessages.length - 1
          ? {
              ...m,
              content:
                typeof m.content === 'string'
                  ? [{ type: 'text' as const, text: m.content, cache_control: { type: 'ephemeral' } }]
                  : m.content,
            }
          : m,
      ),
      // (4) New content: never cached, by design.
      newUserContent,
    ],
  });
}
